{
  "name": "PhoxX 激光器",
  "name_en": "PhoxX laser",
  "manufacturer": "",
  "description": "实验室激光光源，可提供可控的激光输出，常用于显微成像、荧光激发以及一般光学实验中的照明或激发。",
  "description_en": "A laboratory laser light source with controllable output, commonly used for microscopy, fluorescence excitation, and general optical experiments.",
  "tag_hints": [
    "laser source",
    "microscopy excitation",
    "fluorescence excitation",
    "optical experiments",
    "output power control"
  ],
  "actions": [
    {
      "action_name": "auto-IsOn",
      "description": "获取激光器是否开启",
      "description_en": "Get whether the laser is on."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "打开激光输出",
      "description_en": "Turn on laser emission."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭激光输出",
      "description_en": "Turn off laser emission."
    },
    {
      "action_name": "auto-SetPower",
      "description": "设置激光输出功率",
      "description_en": "Set the laser output power."
    },
    {
      "action_name": "auto-Close",
      "description": "关闭设备连接",
      "description_en": "Close the device connection."
    },
    {
      "action_name": "auto-GetOutputmW",
      "description": "获取当前输出功率（毫瓦）",
      "description_en": "Get the current output power in milliwatts."
    },
    {
      "action_name": "auto-GetStatusText",
      "description": "获取设备状态文本",
      "description_en": "Get the device status text."
    },
    {
      "action_name": "auto-GetPower",
      "description": "获取功率设定值",
      "description_en": "Get the configured power setting."
    }
  ]
}

